+	branch: string | null;
+	hasUpstream: boolean;
+	ahead: number;
+	behind: number;
+	staged: SourceControlFile[];
+	unstaged: SourceControlFile[];
+	untracked: SourceControlFile[];
+	commits: SourceControlCommit[];
+};
