+		await git([
+			"status",
+			"--porcelain=v1",
+			"-z",
+			"--branch",
+			"--untracked-files=all",
+		]),
+	);
+	const [stagedCounts, unstagedCounts, logOutput, unpushedOutput] =
+		await Promise.all([
+			git(["diff", "--cached", "--numstat", "-z"]).then(
+				parseNumstat,
+				() => new Map(),
+			),
+			git(["diff", "--numstat", "-z"]).then(parseNumstat, () => new Map()),
