+export type CommitFile = {
+	path: string;
+	/** Previous path when the commit renamed the file. */
+	originalPath?: string;
+	status: SourceControlStatus;
+	additions: number | null;
+	deletions: number | null;
+};
+
+export type CommitDetails = {
+	environmentId: string;
+	sha: string;
+	files: CommitFile[];
+};
